draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw trees
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 - 50, H/2 - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 50, H/2 - 100);
  ctx.stroke();

  // draw fog
  ctx.fillStyle = 'rgba(200, 200, 200, ' + (0.5 + 0.5 * Math.sin(t)) + ')';
  ctx.fillRect(0, H/2 + 50 + 50 * Math.sin(t), W, H/2 - 50 - 50 * Math.sin(t));

  // draw sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 150 + 50 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
